"use client";

import { SiGithub, SiX, SiYoutube } from "@icons-pack/react-simple-icons";
import { ExternalLink } from "lucide-react";
import { motion } from "motion/react";
import Image from "next/image";

import { Spinner } from "@/components/Spinner";
import type { KitzeApp } from "@/components/ui/KitzeAppsProvider";
import { useKitzeApps } from "@/components/ui/KitzeAppsProvider";
import { cn } from "@/lib/utils";

const socials = [
  {
    icon: SiX,
    name: "X",
    url: "https://x.com/thekitze",
  },
  {
    icon: SiGithub,
    name: "GitHub",
    url: "https://github.com/kitze",
  },
  {
    icon: SiYoutube,
    name: "YouTube",
    url: "https://youtube.com/@thekitze",
  },
];
export interface MadeByKitzeProps {
  /** App name to exclude from the list (typically the current app) */
  excludeApp?: string;
  /** Custom apps list (overrides fetched) */
  apps?: KitzeApp[];
  /** Additional className */
  className?: string;
  /** Profile image URL */
  profileImage?: string;
  /** Show "View all projects" link */
  showViewAll?: boolean;
}
export const MadeByKitze = ({
  excludeApp,
  apps: customApps,
  className,
  profileImage = "https://www.kitze.io/avatar.jpg",
  showViewAll = true,
}: MadeByKitzeProps) => {
  const { apps: fetchedApps, isLoading } = useKitzeApps();
  const apps = customApps || fetchedApps;
  const filteredApps = excludeApp
    ? apps.filter((app) => app.name.toLowerCase() !== excludeApp.toLowerCase())
    : apps;
  if (isLoading && !customApps) {
    return (
      <div className="flex justify-center p-8" aria-label="Loading projects">
        <Spinner />
      </div>
    );
  }
  return (
    <section
      className={cn(
        "border-t border-white/5 bg-black py-24 md:py-32",
        className
      )}
    >
      <div className="container mx-auto px-6 md:px-12 lg:px-20">
        {/* Header */}
        <div className="mb-16 flex items-center gap-6">
          <Image
            unoptimized
            width={80}
            height={80}
            src={profileImage}
            alt="Kitze"
            className="h-20 w-20 rounded-full border border-white/10"
          />
          <div>
            <div className="mb-1 text-xs font-medium tracking-widest text-zinc-500 uppercase">
              From the maker
            </div>
            <a
              href="https://kitze.io"
              target="_blank"
              rel="noopener noreferrer"
              className="transition-opacity hover:opacity-80"
            >
              <h2 className="mb-3 text-3xl font-bold tracking-tight text-white">
                More by Kitze
              </h2>
            </a>

            <div className="flex items-center gap-1">
              {socials.map((social) => (
                <a
                  key={social.name}
                  href={social.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="cursor-pointer rounded-lg p-1.5 text-zinc-500 transition-all hover:bg-white/5 hover:text-white"
                  aria-label={social.name}
                >
                  <social.icon className="h-4 w-4" />
                </a>
              ))}
            </div>
          </div>
        </div>

        {/* Grid */}
        <div className="grid grid-cols-1 gap-4 md:grid-cols-2 lg:grid-cols-3">
          {filteredApps.map((app, index) => (
            <motion.a
              key={app.name}
              href={app.url}
              target="_blank"
              rel="noopener noreferrer"
              initial={{
                opacity: 0,
                y: 20,
              }}
              whileInView={{
                opacity: 1,
                y: 0,
              }}
              viewport={{
                once: true,
              }}
              transition={{
                delay: index * 0.05,
              }}
              className="group flex cursor-pointer flex-col rounded-xl border border-white/5 bg-zinc-900/20 p-6 transition-all duration-300 hover:border-white/10 hover:bg-zinc-900/40"
            >
              <div className="mb-4 flex items-start justify-between">
                <h3 className="text-lg font-semibold text-zinc-200 transition-colors group-hover:text-white">
                  {app.name}
                </h3>
                <ExternalLink className="h-4 w-4 text-zinc-700 transition-colors group-hover:text-zinc-500" />
              </div>

              <p className="mb-2 text-sm font-medium text-zinc-400 transition-colors group-hover:text-zinc-300">
                {app.tagline}
              </p>

              <p className="line-clamp-2 text-sm leading-relaxed text-zinc-500">
                {app.description}
              </p>
            </motion.a>
          ))}
        </div>

        {/* Footer Link */}
        {showViewAll && (
          <div className="mt-16 text-center">
            <a
              href="https://kitze.io/projects"
              target="_blank"
              rel="noopener noreferrer"
              className="inline-flex items-center gap-2 text-sm text-zinc-600 transition-colors hover:text-zinc-400"
            >
              View all projects <ExternalLink className="h-3 w-3" />
            </a>
          </div>
        )}
      </div>
    </section>
  );
};

"use client";

import { ExternalLink } from "lucide-react";

import { useKitzeApps } from "@/components/ui/KitzeAppsProvider";
import { cn } from "@/lib/utils";

export interface KitzeAppLink {
  name: string;
  url: string;
}

export interface FooterColumnKitzeAppsProps {
  /** App name to exclude from the list (typically the current app) */
  excludeApp?: string;
  /** Ref parameter to append to URLs */
  refParam?: string;
  /** Custom apps list (overrides fetched) */
  apps?: KitzeAppLink[];
  /** Custom title */
  title?: string;
  /** Additional className */
  className?: string;
}

export const FooterColumnKitzeApps = ({
  excludeApp,
  refParam,
  apps: customApps,
  title = "More by Kitze",
  className,
}: FooterColumnKitzeAppsProps) => {
  const { apps: fetchedApps, isLoading } = useKitzeApps();

  const apps =
    customApps || fetchedApps.map((a) => ({ name: a.name, url: a.url }));
  const filteredApps = excludeApp
    ? apps.filter((app) => app.name.toLowerCase() !== excludeApp.toLowerCase())
    : apps;

  const getUrl = (url: string) => {
    if (!refParam) {
      return url;
    }
    const separator = url.includes("?") ? "&" : "?";
    return `${url}${separator}ref=${refParam}`;
  };

  if (isLoading && !customApps) {
    return null;
  }

  return (
    <div className={cn("space-y-4", className)}>
      <h4 className="flex items-center gap-2 text-sm font-semibold text-white">
        {title}
        <span className="text-[10px] font-normal text-zinc-600">&#8599;</span>
      </h4>
      <div className="flex flex-col gap-3 text-sm text-zinc-500">
        {filteredApps.map((app) => (
          <a
            key={app.name}
            href={getUrl(app.url)}
            target="_blank"
            rel="noopener noreferrer"
            className="group flex cursor-pointer items-center gap-1 transition-colors hover:text-white"
          >
            {app.name}
            <ExternalLink className="h-3 w-3 opacity-0 transition-opacity group-hover:opacity-50" />
          </a>
        ))}
      </div>
    </div>
  );
};

"use client";

import { cn } from "@/lib/utils";

export interface ConnectLink {
  label: string;
  url: string;
}

const defaultLinks: ConnectLink[] = [
  { label: "Twitter / X", url: "https://x.com/thekitze" },
  { label: "Support", url: "mailto:hi@kitze.io" },
  { label: "kitze.io", url: "https://kitze.io" },
];

export interface FooterColumnConnectProps {
  /** Custom links list (overrides default) */
  links?: ConnectLink[];
  /** Ref parameter to append to URLs (only for http links) */
  refParam?: string;
  /** Custom title */
  title?: string;
  /** Additional className */
  className?: string;
}

export const FooterColumnConnect = ({
  links = defaultLinks,
  refParam,
  title = "Connect",
  className,
}: FooterColumnConnectProps) => {
  const getUrl = (url: string) => {
    if (!refParam) {
      return url;
    }
    // Don't add ref to mailto or non-http links
    if (!url.startsWith("http")) {
      return url;
    }
    const separator = url.includes("?") ? "&" : "?";
    return `${url}${separator}ref=${refParam}`;
  };

  return (
    <div className={cn("space-y-4", className)}>
      <h4 className="text-sm font-semibold text-white">{title}</h4>
      <div className="flex flex-col gap-3 text-sm text-zinc-500">
        {links.map((link) => (
          <a
            key={link.label}
            href={getUrl(link.url)}
            target={link.url.startsWith("http") ? "_blank" : undefined}
            rel={
              link.url.startsWith("http") ? "noopener noreferrer" : undefined
            }
            className="cursor-pointer transition-colors hover:text-white"
          >
            {link.label}
          </a>
        ))}
      </div>
    </div>
  );
};

"use client";

import { cn } from "@/lib/utils";

export interface FooterBottomProps {
  /** Variant of the "built by" text */
  variant?: "full" | "minimal";
  /** Additional className */
  className?: string;
}
export const FooterBottom = ({
  variant = "full",
  className,
}: FooterBottomProps) => (
  <div
    className={cn(
      "mt-16 flex flex-col items-center justify-between gap-4 border-t border-white/5 pt-8 sm:flex-row",
      className
    )}
  >
    <div className="text-xs text-zinc-600">
      © {new Date().getFullYear()} Kitze. All rights reserved.
    </div>
    <div className="flex items-center gap-2 text-xs text-zinc-600">
      {variant === "full" ? (
        <>
          <span>&quot;Built&quot; by</span>
          <a
            href="https://x.com/thekitze"
            target="_blank"
            rel="noopener noreferrer"
            className="cursor-pointer text-zinc-400 transition-colors hover:text-white"
          >
            @thekitze
          </a>
          <span>with</span>
          <span className="inline-flex gap-1">
            <span>😡</span>
            <span>&</span>
            <span>swearing at LLMs</span>
          </span>
        </>
      ) : (
        <>
          <span>Made by</span>
          <a
            href="https://x.com/thekitze"
            target="_blank"
            rel="noopener noreferrer"
            className="cursor-pointer text-zinc-400 transition-colors hover:text-white"
          >
            @thekitze
          </a>
        </>
      )}
    </div>
  </div>
);

"use client";

import type { ReactNode } from "react";
import { createContext, useContext, useEffect, useMemo, useState } from "react";
import { z } from "zod";

export interface KitzeApp {
  name: string;
  tagline: string;
  description: string;
  url: string;
}
const projectSchema = z.object({
  externalUrl: z.string().optional(),
  subtitle: z.string(),
  summary: z.string(),
  title: z.string(),
});

const PROJECTS_API_URL = "https://www.kitze.io/api/projects?apps=true";
interface KitzeAppsContextType {
  apps: KitzeApp[];
  isLoading: boolean;
}
const KitzeAppsContext = createContext<KitzeAppsContextType>({
  apps: [],
  isLoading: true,
});
export const useKitzeApps = () => useContext(KitzeAppsContext);
interface KitzeAppsProviderProps {
  children: ReactNode;
}
export const KitzeAppsProvider = ({ children }: KitzeAppsProviderProps) => {
  const [apps, setApps] = useState<KitzeApp[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  useEffect(() => {
    const controller = new AbortController();
    const loadProjects = async () => {
      try {
        const response = await fetch(PROJECTS_API_URL, {
          signal: controller.signal,
        });
        if (!response.ok) {
          throw new Error(`Projects request failed: ${response.status}`);
        }
        const projects = z.array(projectSchema).parse(await response.json());
        const mapped = projects.flatMap((project) =>
          project.externalUrl
            ? [
                {
                  description: project.summary,
                  name: project.title,
                  tagline: project.subtitle,
                  url: project.externalUrl,
                },
              ]
            : []
        );
        if (!controller.signal.aborted) {
          setApps(mapped);
        }
      } catch (error) {
        if (!controller.signal.aborted) {
          console.error("Failed to fetch projects:", error);
        }
      } finally {
        if (!controller.signal.aborted) {
          setIsLoading(false);
        }
      }
    };
    void loadProjects();
    return () => controller.abort();
  }, []);
  const contextValue = useMemo(() => ({ apps, isLoading }), [apps, isLoading]);
  return (
    <KitzeAppsContext.Provider value={contextValue}>
      {children}
    </KitzeAppsContext.Provider>
  );
};
